return [
  { json: { source: 'Freelancer.com',   url: 'https://www.freelancer.com/rss.xml' } },
  { json: { source: 'We Work Remotely', url: 'https://weworkremotely.com/categories/remote-devops-sysadmin-jobs.rss' } },
  { json: { source: 'HN Jobs',          url: 'https://hnrss.org/jobs' } },
];

// Tiered keywords: a generic word alone must not qualify a job.
const STRONG = ['kubernetes','k8s','terraform','ansible','argocd','argo cd','helm','rancher','harbor',
  'vault','gitlab','jenkins','github actions','docker','docker compose','self-hosted','self hosted',
  'vps','nginx','apache','haproxy','traefik','caddy','sre','prometheus','grafana','ci/cd','cicd',
  'proxmox','n8n','devops','sysadmin','system administrator','load balancer','plesk','cpanel'];

const WEAK = ['linux','ubuntu','debian','centos','aws','gcp','azure','ssl','tls','cloudflare',
  'postgres','postgresql','mysql','mariadb','redis','mongodb','infrastructure','deployment','deploy',
  'automation','server','monitoring','backup','migration','hardening','firewall','ssh','dns',
  'bash','systemd','cron'];

// Hard drop: ad fraud, engagement farming, bot work. Never worth bidding on.
const NEGATIVE = ['ad view','ad viewer','ad-viewing','ad viewing','viewing ads','watch ads','watching ads',
  'click bot','clickbot','auto click','autoclick','bot farm','fake account','followers','captcha',
  'airdrop','crypto mining','mining rig','spam bot','engagement bot','view bot'];

const MIN_SCORE      = 4;   // one strong hit in the body (3) is not enough on its own
const MIN_BUDGET_USD = 80;  // matches the fixed-price floor
const MIN_HOURLY_USD = 15;

// Rough FX, only used to reject obviously tiny budgets. Not accounting-grade.
const FX = {USD:1,EUR:1.09,GBP:1.27,AUD:0.65,CAD:0.73,NZD:0.60,SGD:0.74,HKD:0.128,CHF:1.12,
  INR:0.012,PKR:0.0036,BDT:0.0084,LKR:0.0033,PHP:0.017,MYR:0.22,THB:0.029,IDR:0.000062,VND:0.00004,
  CNY:0.14,JPY:0.0065,KRW:0.00073,TWD:0.031,AED:0.27,SAR:0.27,ILS:0.27,ZAR:0.055,NGN:0.00065,
  BRL:0.18,MXN:0.05,ARS:0.001,CLP:0.001,COP:0.00025,PLN:0.25,SEK:0.095,DKK:0.145,NOK:0.09,
  CZK:0.043,RON:0.22,HUF:0.0028,TRY:0.029,RUB:0.011,UAH:0.024,EGP:0.021};

const ENT = {'&nbsp;':' ','&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&#39;':"'"};
const strip = s => String(s || '').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&amp;|&lt;|&gt;|&quot;|&#39;/g, m => ENT[m]).replace(/\s+/g, ' ').trim();
const escRe = s => s.replace(/[.*+?^${}()|[\]\\\/]/g, '\\$&');
const rx = k => new RegExp('(^|[^a-z0-9])' + escRe(k) + '(?![a-z0-9])', 'i');
const RX_STRONG = STRONG.map(k => [k, rx(k)]);
const RX_WEAK   = WEAK.map(k => [k, rx(k)]);
const RX_NEG    = NEGATIVE.map(k => [k, rx(k)]);
const hostOf = u => (String(u).match(/^https?:\/\/([^\/:?#]+)/i) || [])[1] || '';

// "Budget: ₹100 - ₹400 INR" / "$250 - $750 USD" -> {usd, hourly} or null when absent
function budgetUsd(text) {
  const m = text.match(/Budget:\s*([^)]*?)(?:,\s*Jobs:|\)|$)/i);
  if (!m) return null;
  const raw = m[1].trim();
  const cur = (raw.match(/\b([A-Z]{3})\b/) || [])[1];
  const rate = cur && FX[cur] !== undefined ? FX[cur] : null;
  const nums = (raw.match(/[\d][\d,.]*/g) || [])
    .map(n => parseFloat(n.replace(/,/g, ''))).filter(n => !isNaN(n));
  if (!nums.length || rate === null) return { raw, usd: null, hourly: /hour|hr\b/i.test(raw) };
  return { raw, usd: Math.max(...nums) * rate, hourly: /hour|hr\b/i.test(raw) };
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.link) continue;

  const host = hostOf(j.link).toLowerCase();
  let source = host || 'unknown';
  if (host.includes('freelancer.com')) source = 'Freelancer.com';
  else if (host.includes('weworkremotely')) source = 'We Work Remotely';
  else if (String(j.comments || '').includes('news.ycombinator.com') || host.includes('ycombinator')) source = 'HN Jobs';

  const title = strip(j.title);
  const desc  = strip(j['content:encoded'] || j.content || j.contentSnippet || j.description || '');
  const hay   = title + ' ' + desc;

  const neg = RX_NEG.filter(([k, r]) => r.test(hay)).map(([k]) => k);
  if (neg.length) continue;                       // ad fraud / bot farming: drop outright

  const sTitle = RX_STRONG.filter(([k, r]) => r.test(title)).map(([k]) => k);
  const sBody  = RX_STRONG.filter(([k, r]) => r.test(desc)).map(([k]) => k);
  const strong = [...new Set([...sTitle, ...sBody])];
  if (!strong.length) continue;                   // a generic word alone never qualifies

  const wTitle = RX_WEAK.filter(([k, r]) => r.test(title)).map(([k]) => k);
  const wBody  = RX_WEAK.filter(([k, r]) => r.test(desc)).map(([k]) => k);
  const weak   = [...new Set([...wTitle, ...wBody])];

  const score = sTitle.length * 6 + (sBody.length - sTitle.filter(k => sBody.includes(k)).length) * 3
              + wTitle.length * 2 + (wBody.length - wTitle.filter(k => wBody.includes(k)).length) * 1;
  if (score < MIN_SCORE) continue;

  const b = budgetUsd(desc);
  if (b && b.usd !== null) {
    const floor = b.hourly ? MIN_HOURLY_USD : MIN_BUDGET_USD;
    if (b.usd < floor) continue;                  // below the floor we agreed; not worth Connects
  }

  out.push({ json: {
    source, title, link: j.link,
    type: source === 'Freelancer.com' ? 'Freelance' : (j.type || 'Full-time'),
    budget: b ? b.raw : null,
    budgetUsd: b && b.usd !== null ? Math.round(b.usd) : null,
    published: j.isoDate || j.pubDate || null,
    summary: desc.slice(0, 280),
    matched: [...strong, ...weak], strong, score,
  }});
}
return out;

const j = $input.item.json;
const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const flag = j.score >= 4 ? '🔥' : '🟢';
const meta = [j.source, j.type, j.budget].filter(Boolean).join(' · ');
const message = [
  `${flag} <b>${esc(j.title)}</b>`,
  esc(meta),
  `Matched: ${esc(j.matched.join(', '))}`,
  '',
  esc(j.summary),
  '',
  j.link,
].join('\n');
return { json: { ...j, message } };
